# region: emit
def emit(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: gather
def gather(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(digest(render(emit(raw))))

